// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Düzenli ifadeler (regex), sonlu durum makineleri, özyineleme (recursion) izleme, yığınla ifade değerlendirme ve derleyici aşamaları (zor).
const ozComputing16Zor = <(String, String, List<String>, String)>[
  ('Fiyat etiketlerinden yalnızca sonunda \'TL\' birimi bulunan sayıları çekmek ama \'TL\' harflerini eşleşme sonucuna dahil etmemek için \'\\d+(?=\\s*TL)\' kullanılır. Buradaki \'(?=...)\' yapısına ne ad verilir?', 'Pozitif ileriye bakış (positive lookahead)', ['Negatif geriye bakış (negative lookbehind)', 'Tembel niceleyici (lazy quantifier)', 'Atomik geri referans (atomic backreference)'], '(?=...) pozitif ileriye bakış, imleci ilerletmeden ve karakter tüketmeden sağ taraftaki koşulun varlığını doğrular.'),
  ('Bir kaynak kod tarayıcısında \'foo\' fonksiyon çağrılarını bulmak, ancak \'foo(\' şeklinde parantezle devam etmeyen \'foobar\' gibi değişkenleri seçmek için \'foo(?!\\()\' deseni yazılmıştır. \'(?!\\()\' ne yapar?', 'Hemen sağında açılış parantezi bulunmayan \'foo\' geçişlerini doğrular', ['Yalnızca parantez içinde argüman olarak yazılmış \'foo\' kelimelerini yakalar', 'Açılış parantezini silerek metni doğrudan \'foo\' dizgesine dönüştürür', 'Ünlem işareti ve parantezin yan yana geldiği sözdizimi hatalarını listeler'], '(?!...) negatif ileriye bakış (negative lookahead) yapısıdır; içindeki desen hemen arkadan gelmiyorsa eşleşmeyi onaylar.'),
  ('Köşeli parantez içinde yazılan \'[a-z-_]\' ifadesinin ortasındaki tire (-) ile sonundaki tire (-) arasındaki fark nedir?', 'İlk tire karakter aralığı tanımlarken sınıfın en sonundaki tire düz tire karakterini temsil eder', ['Her iki tire de çıkarma operatörü olarak çalışıp harfleri kümeden çıkarır', 'İlk tire düz karakter olarak aranırken sondaki tire satır devamını simgeler', 'Sınıf içinde birden fazla tire yazılması tüm düzenli ifade motorlarında sözdizimi hatası üretir'], 'Karakter sınıfında iki karakter arasındaki \'-\' aralık (a\'dan z\'ye) belirtir; başta veya sonda duran \'-\' ise edebi (literal) tire karakteridir.'),
  ('Bir web sunucusu saldırgan bir girdide \'aaaaaaaaaaaaaaaaaaaaaaaaaaaa!\' dizgesini \'^(a+)+\$\' deseniyle doğrulamaya çalıştığında işlemcinin aşırı yavaşlamasına (ReDoS) ne yol açar?', 'İç içe tekrar niceleyicilerinin sondaki ünlem yüzünden üstel sayıda geri izleme (catastrophic backtracking) yapması', ['Ünlem işaretinin düzenli ifade motorunda sonsuz döngü başlatan özel bir kesme komutu olması', 'Dizge uzunluğunun 16 baytı aşması nedeniyle bellek yığınının doğrudan diske yazılması', 'Şapka ve dolar çıpalarının aynı anda kullanılmasının karakter kodlamasını bozması'], 'NFA tabanlı regex motorlarında (a+)+ gibi belirsiz iç içe niceleyiciler, eşleşme sonda başarısız olduğunda \'a\' harflerini bölmenin 2^n yolunu dener.'),
  ('Tek harfli \'o\' gibi dizgelerin de \'ünlü harfle başlayıp ünlü harfle bitenler\' kümesine dahil edilmesi için \'^[aeiou].*[aeiou]\$\' ifadesi nasıl düzeltilebilir?', '^[aeiou](.*[aeiou])?\$', ['^[aeiou]+[aeiou]+\$', '^[aeiou].+[aeiou]\$', '^([aeiou].*){2}\$'], 'İkinci ünlü ve aradaki karakterleri isteğe bağlı \'(.*[aeiou])?\' yapmak tek ünlü harfli dizgelerin de kabulünü sağlar.'),
  ('Aşağıdaki düzenli ifadelerden hangisi yalnızca çift tam sayıları (negatifler ve sıfır dahil, baştaki gereksiz sıfırlar hariç: 0, -2, 14, -108 vb.) doğru biçimde tanımlar?', '^(0|-?[1-9]\\d*[02468]|-?[2468])\$', ['^-?\\d*[02468]\$', '^[02468]+\$', '^-?[1-9][02468]\$'], '\'-?\\d*[02468]\' ifadesi \'-0\' ve \'002\' gibi geçersiz yazılımları kabul eder; doğru ifade 0\'ı, tek basamaklı çiftleri ve sonu çift olan çok basamaklıları ayırır.'),
  ('Bir CSV satırında çift tırnak içindeki metinleri ayıklamak için \'"[^"]*"\' deseni kullanmanın \'"(.*?)"\' desenine göre performans avantajı nedir?', 'Olumsuz karakter sınıfı tırnak görene kadar geri izleme yapmadan doğrusal zamanda ilerler', ['Çift tırnak içindeki kaçırılmış tırnakları ekstra kural gerekmeden kendiliğinden çözer', 'Bellekte üç ayrı yakalama grubu oluşturarak alt alanlara hızlı erişim sunar', 'Satır sonu karakterlerini otomatik olarak virgül ayırıcısına dönüştürür'], '[^"]* ifadesi kapanış tırnağıyla çakışmadığından tembel niceleyicideki adım adım kontrol ve olası geri izleme maliyetini ortadan kaldırır.'),
  ('Bir parola doğrulayıcısında \'^(?=.*[A-Z])(?=.*\\d).{8,}\$\' düzenli ifadesi neyi denetler?', 'En az 8 karakter uzunluğunda olup içinde en az bir büyük harf ve en az bir rakam bulunmasını', ['Tam olarak 8 karakterden oluşup ilk karakterinin büyük harf, son karakterinin rakam olmasını', 'Yalnızca büyük harfler ve rakamlardan oluşup küçük harf veya sembol içermemesini', 'Büyük harflerin tümünün rakamlardan daha önce yazılmış olmasını'], 'Başlangıçtaki iki pozitif ileriye bakış (lookahead) bağımsız olarak büyük harf ve rakam varlığını sınar; \'.{8,}\' ise minimum 8 uzunluğu sağlar.'),
  ('MAC adreslerini \'00:1A:2B:3C:4D:5E\' veya \'00-1A-2B-3C-4D-5E\' biçiminde kabul eden, ancak aynı adreste \':\' ve \'-\' ayırıcılarının karışık kullanımını (\'00:1A-2B:3C:4D:5E\') engelleyen desen hangisidir?', '^[0-9A-Fa-f]{2}([-:])([0-9A-Fa-f]{2}\\1){4}[0-9A-Fa-f]{2}\$', ['^([0-9A-Fa-f]{2}[-:]){5}[0-9A-Fa-f]{2}\$', '^[0-9A-Fa-f]{2}:[0-9A-Fa-f]{2}-[0-9A-Fa-f]{8}\$', '^([0-9A-Fa-f]{2}){6}[-:]\$'], 'İlk ayırıcı \'([ -:])\' ile 1. gruba yakalanır ve sonraki dört ayırıcıda \'\\1\' geri referansı kullanılarak aynı ayırıcının tekrarı zorunlu kılınır.'),
  ('Düzenli ifadelerde \'\\B\' (büyük B) meta karakteri hangi konumlarla eşleşir?', 'Kelime sınırı olmayan konumlarla, örneğin iki harfin tam ortasıyla', ['Yalnızca satır başındaki boşluk ve sekme dizilerinin başlangıcıyla', 'İkili sayı sistemindeki yalnızca 0 ve 1 rakamlarından oluşan bloklarla', 'Parantez gruplarının kapanış noktasındaki bellek işaretçileriyle'], '\\B, \\b kelime sınırının tersidir; \'akşam\' içindeki \'k\' ile \'ş\' arası gibi kelime içi veya iki boşluk arası konumlarda eşleşir.'),
  ('Bir metin üzerinde \'a*\' düzenli ifadesiyle genel arama yapıldığında \'bbb\' dizgesinde kaç adet sıfır uzunluklu (boş) eşleşme meydana gelir?', '4', ['0', '3', '1'], '3 karakterli \'bbb\' dizgesinde karakterlerin başı, araları ve sonu olmak üzere 4 konum vardır; \'a*\' sıfır \'a\' ile bu 4 konumun hepsinde eşleşir.'),
  ('Neden \'/\\*[^*]*\\*/\' deseni C tarzı \'/* ... */\' yorum bloklarını yakalamakta yetersiz kalır?', 'Yorum metninin kendi içinde tek başına geçen \'*\' karakteri bulunduğunda eşleşme yarıda kesilir', ['Ters eğik çizgi karakteri eğik çizginin anlamını ortadan kaldırarak sözdizimi hatası verir', 'Yorumun içinde hiç boşluk karakteri bulunmadığında desen eşleşmeyi reddeder', 'Açılış ve kapanış işaretleri arasındaki rakamları otomatik olarak siler'], '\'/* çarpma: a * b */\' gibi içinde yıldız bulunan geçerli bir yorumda \'[^*]*\' ortadaki yıldızı geçemez.'),
  ('İç içe parantez içeren \'^((a)(b))\\3\$\' düzenli ifadesinde \'\\3\' geri referansı hangi alt dizgeyle eşleşir?', 'b', ['ab', 'a', 'abb'], 'Yakalama grupları sol açılış parantezlerinin sırasına göre numaralanır: 1. grup \'(ab)\', 2. grup \'(a)\', 3. grup \'(b)\' olur.'),
  ('İçinde hiç \'11\' alt dizgesi bulunmayan (yani ardışık iki tane 1 içermeyen) tüm ikili dizgeleri tanımlayan düzenli ifade hangisidir?', '^0*(10+)*1?\$', ['^(01)*\$', '^[01]*[^11]\$', '^1?0*1?\$'], 'Her \'1\' karakterinden sonra dizge bitmiyorsa en az bir \'0\' gelmelidir; \'^0*(10+)*1?\$\' bu koşulu sağlayan tüm ikili dizgeleri eksiksiz üretir.'),
  ('Çoğu klasik düzenli ifade motorunda geriye bakış (lookbehind) ifadelerine getirilen yaygın kısıtlama nedir?', 'Geriye bakış deseninin sabit veya sınırlı uzunlukta olması, belirsiz \'*\' ya da \'+\' içermemesi', ['Geriye bakış içinde hiçbir şekilde rakam veya harf sınıfı kullanılamaması', 'Bir düzenli ifadede en fazla bir adet çıpa karakteriyle birlikte yazılabilmesi', 'Yalnızca satırın en son karakterinden geriye doğru çalışabilmesi'], 'Motorun mevcut konumdan kaç karakter geriye gidip kontrol başlatacağını bilmesi için klasik PCRE/Python motorları sabit uzunluklu lookbehind şartı koyar.'),
  ('Saf (geri referanssız, matematiksel) düzenli ifadelerin keyfi derinlikte iç içe geçmiş HTML/XML etiketlerini (\'<div><div>...</div></div>\') doğrulayamamasının kuramsal nedeni nedir?', 'Düzenli ifadelerin sonlu belleğe sahip olması ve sınırsız derinlikteki açılış-kapanış sayısını tutamaması', ['HTML etiketlerinde kullanılan eğik çizgi karakterinin düzenli ifadelerde tanımlanamaması', 'Bir düzenli ifadenin toplam karakter uzunluğunun en fazla 255 bayt ile sınırlandırılması', 'Açısal parantezlerin her zaman aritmetik karşılaştırma operatörü olarak işlenmesi'], 'Keyfi derinlikte dengeli iç içe yapılar bağlamdan bağımsız dillerdir; sonlu durum otomatiğine denk olan saf düzenli ifadeler sınırsız sayaç tutamaz.'),
  ('Atomik gruplama \'(?>...)\' veya sahiplenici niceleyici \'a++\' (possessive quantifier) özelliğinin temel işlevi nedir?', 'Tüketilen karakterleri kilitleyerek eşleşme sonradan başarısız olsa bile geri izlemeyi (backtracking) yasaklamak', ['Desenin metin içinde sağdan sola doğru ters yönde taranmasını başlatmak', 'Aynı karakterin hem büyük hem küçük harf biçimlerini aynı anda yakalamak', 'Eşleşen alt dizgeleri alfabetik sıraya dizerek dizi halinde döndürmek'], 'Sahiplenici niceleyiciler aldıkları karakterleri asla geri bırakmaz; bu sayede ReDoS benzeri gereksiz geri izlemeleri önleyerek hız kazandırır.'),
  ('PCRE, Python ve JavaScript gibi modern dillerdeki düzenli ifade motorlarının \'([a-z]+)\\1\' gibi geri referanslar içermesi kuramsal açıdan ne doğurur?', 'Düzenli dillerin ötesine geçerek bazı düzenli olmayan dilleri de tanıyabilmelerini ancak en kötü durumda üstel süre alabilmelerini', ['Bellek tüketimini sıfıra indirerek her desenin sabit O(1) karmaşıklıkta çalışmasını', 'Bağlamdan bağımsız tüm dilleri parantez derinliği fark etmeksizin çözebilmelerini', 'Deterministik sonlu otomata (DFA) her zaman tek adımda dönüştürülebilmelerini'], 'Geri referanslar {ww | w in Σ*} gibi bağlamdan bağımsız bile olmayan bir dili tanıyabilir; bu yüzden PCRE \'regex\'leri kuramsal düzenli ifadelerden daha geniştir ve eşleştirme NP-zor hale gelebilir.'),
  ('Bir sürüm numarasını Anlamsal Sürümleme (SemVer) temel yapısına göre \'1.0.0\' veya \'2.14.3\' gibi üç negatif olmayan tam sayı (başta gereksiz sıfır olmadan) olarak doğrulayan desen hangisidir?', '^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\$', ['^\\d+\\.\\d+\\.\\d+\$', '^[1-9]+\\.[0-9]+\\.[0-9]+\$', '^(0|[1-9])+\\.{2}(0|[1-9])+\$'], 'SemVer kuralında \'01.2.3\' geçersizdir; \'(0|[1-9]\\d*)\' sıfıra tek başına izin verirken çok basamaklı sayılarda başlangıç sıfırını engeller.'),
  ('Aynı ardışıl işlevi gerçekleştiren bir Mealy makinesi ile Moore makinesi karşılaştırıldığında genellikle hangi sonuç görülür?', 'Mealy makinesi daha az durum kullanabilir ve girdideki değişime aynı çevrimde daha erken tepki verir', ['Moore makinesi hiçbir zaman bellek yazmacına (flip-flop) ihtiyaç duymadan çalışır', 'Mealy makinesinin çıktıları saat darbesine kadar kesinlikle değişmeden sabit kalır', 'Moore makinesi durum geçişlerinde girdi sinyallerini tamamen görmezden gelir'], 'Mealy makinesi çıktıyı geçiş anında ürettiği için çoğunlukla 1 saat darbesi erken yanıt verir ve durum birleştirmeye daha elverişlidir.'),
  ('Güvercin Yuvası İlkesine dayanan Düzenli Diller İçin Pompalama Lemması (Pumping Lemma), k durumlu bir DFA\'nın k veya daha uzun bir dizgeyi işlerken neyin kaçınılmaz olduğunu söyler?', 'Hesaplama yolu üzerinde en az bir durumun birden fazla kez ziyaret edilerek bir döngü oluşturmasının', ['Dizgenin ortasındaki karakterlerin tamamının tuzak durumuna yönlendirilmesinin', 'Makinenin bellek taşması yaşayarak başlangıç durumuna sıfırlanmasının', 'Kabul durumlarının sayısının girdi uzunluğuyla orantılı biçimde ikiye katlanmasının'], 'Uzunluğu k olan bir dizge okunurken başlangıç dahil k+1 durum adımı atılır; k durum olduğundan Güvercin Yuvası İlkesi gereği en az bir durum tekrarlanır.'),
  ('Bir öğrenci \'En fazla 100 adet açılış parantezi ve ona karşılık gelen eşit sayıda kapanış parantezi içeren a^n b^n (0 <= n <= 100) dili düzenli değildir çünkü sayma gerektirir\' iddiasında bulunuyor. Bu iddia neden YANLIŞTIR?', 'n üstten sabit bir sayıyla (100) sınırlandığında dil sonlu bir küme olur ve her sonlu dil düzenlidir', ['Sonlu durum otomatları yerleşik bir donanım sayacıyla 1024\'e kadar her dili sayabilir', 'a^n b^n dili üst sınır olmasa bile NFA\'daki epsilon geçişleriyle her zaman tanınabilir', 'Yalnızca asal sayı uzunluğundaki diller düzenli olmaktan çıkar, 100 çift sayıdır'], 'Sonlu sayıda dizge içeren her dil (büyük bile olsa sabit sayıda durumla dallandırılarak) bir DFA tarafından tanınabilir; düzenliliği bozan şey sınırsız (unbounded) n\'dir.'),
  ('{0, 1} alfabesinde sondan üçüncü karakteri \'1\' olan tüm ikili dizgeleri (örneğin \'100\', \'0110\', \'1111\') tanıyan bir NFA yalnızca 4 durumla yazılabilirken, buna eşdeğer en küçük DFA kaç duruma sahip olmalıdır?', '8 durum', ['4 durum', '6 durum', '16 durum'], 'DFA dizgenin ne zaman biteceğini önceden bilemediği için son okunan 3 bitin tamamını hafızada tutmak zorundadır; 2^3 = 8 farklı son üçlü kombinasyonu 8 durum gerektirir.'),
  ('Düzenli dillerin kapalılık (closure) özellikleri göz önüne alındığında, L1 ve L2 düzenli iki dil ise aşağıdaki işlemlerden hangisinin sonucu KESİNLİKLE yine düzenli bir dildir?', 'Simetrik fark: (L1 - L2) ∪', ['L1\'deki her w dizgesinin sağına kendi tersinin eklendiği {w w^R | w ∈ L1} kümesi', 'L1\'deki dizgelerin uzunluklarının karesi kadar \'a\' içeren {a^(n^2)} kümesi', 'Eşit uzunluktaki harf bloklarını eşleyen {a^k b^k | k >= 0} alt kümesi'], 'Düzenli diller birleşim, kesişim, tümleyen ve fark işlemleri altında kapalıdır; dolayısıyla simetrik fark da kesinlikle düzenlidir. Palindromlar ve n^2 sayımı ise düzenli değildir.'),
  ('Bir düzenli dil olan L\'nin tüm dizgelerinin ters çevrilmesiyle elde edilen L^R = {w^R | w ∈ L} dili hakkında ne söylenebilir?', 'L^R de düzenlidir; L\'nin otomatındaki tüm oklar ters çevrilip başlangıç ve kabul rolleri takas edilerek bir NFA kurulabilir', ['Dizgeyi sondan başa okumak yığın belleği gerektirdiğinden L^R bağlamdan bağımsız olur', 'Yalnızca alfabesi tek harfli olan düzenli dillerin tersi alındığında düzenlilik korunur', 'Okların ters çevrilmesi deterministikliği koruduğundan her zaman doğrudan bir DFA elde edilir'], 'Okları ters çevirmek ve eski kabul durumlarından ε-geçişli yeni bir başlangıç durumu kurmak L^R dilini tanıyan geçerli bir NFA verir; dolayısıyla düzenli diller ters çevirme altında kapalıdır.'),
  ('Bir akıllı kilit 4 haneli \'1011\' şifresini kayan pencere (sliding window) yöntemiyle denetlemektedir: kullanıcı art arda bitler girerken son 4 bit \'1011\' olduğu anda kilit açılır. Kullanıcı \'101011\' girdiğinde \'101\' kısmından sonra \'0\' geldiğinde makine neden en başa (0 eşleşme) dönmek yerine \'10\' eşleşmiş duruma geçmelidir?', 'Okunan \'1010\' dizisinin son iki biti olan \'10\', aranan \'1011\' şifresinin geçerli bir öneki olduğu için', ['Sonlu durum makinelerinde başlangıç durumuna geri dönen okların çizilmesi yasaklandığı için', '\'0\' biti her zaman bir önceki durumu koruyan etkisiz eleman olarak tanımlandığı için', 'Kilit şifresindeki \'1\' sayısı çift olduğundan tüm sıfırlar otomatik atlandığı için'], 'KMP benzeri önek-sonek örtüşmesi mantığıyla \'101\' üzerine \'0\' geldiğinde eldeki son kısım \'10\'dur ve yeni bir şifre denemesinin ilk iki harfi zaten tamamlanmıştır.'),
  ('Hiyerarşik durum makinelerinin (Statecharts / UML Durum Diyagramları) klasik düz FSM\'lerdeki \'durum patlaması\' (state explosion) sorununu azaltmak için getirdiği temel yenilik nedir?', 'Üst durumlar (superstates) tanımlayarak ortak geçişlerin alt durumlar adına tek bir okla yazılabilmesi', ['Durum sayısını her zaman en fazla üç düğümle sınırlandıran donanım kısıtı getirmesi', 'Girdi alfabesindeki sembolleri otomatik olarak ikili ASCII kodlarına dönüştürmesi', 'Koşullu dallanmaları tamamen kaldırarak yalnızca doğrusal zincir geçişlere izin vermesi'], 'David Harel\'in Statecharts modelinde örneğin 10 alt durumun hepsinden \'İptal\' olayıyla \'Ana Menü\'ye ayrı ayrı 10 ok çizmek yerine kapsayıcı üst durumdan tek ok çizilir.'),
  ('NFA doğrudan (DFA\'ya dönüştürülmeden) Thompson\'ın paralel durum kümesi izleme yöntemiyle çalıştırıldığında, m durumlu bir NFA\'nın n uzunluklu dizgeyi işlemesinin en kötü durum zaman karmaşıklığı nedir?', 'O(m^2 · n) veya geçiş sayısına göre doğrusal; üstel geri izleme yaşanmaz', ['Her zaman O(2^n) üstel zaman karmaşıklığı', 'Durum sayısından bağımsız sabit O(1) zaman', 'O(n!) faktöriyel zaman karmaşıklığı'], 'Thompson NFA simülasyonu geri izleme (backtracking) yapmak yerine her adımda aktif durumlar kümesini (en fazla m elemanlı) günceller ve ReDoS tuzaklarından etkilenmez.'),
  ('Geçiş tablosu verilen bir DFA\'da Q = {A, B, C}, başlangıç A, kabul F = {C} olsun. δ(A,0)=B, δ(A,1)=A, δ(B,0)=B, δ(B,1)=C, δ(C,0)=B, δ(C,1)=A geçişlerine sahip bu otomat hangi ikili dizgeleri kabul eder?', 'Son iki karakteri \'01\' olan tüm ikili dizgeleri', ['İçinde en az bir kez \'01\' alt dizgesi geçen tüm dizgeleri', 'Başlangıçtaki ilk iki karakteri \'01\' olan tüm dizgeleri', 'Sıfır ve bir sayıları birbirine eşit olan dizgeleri'], 'A başlangıç/sonu 1 (\'11\' vb.), B sonu \'0\' olanlar, C ise B\'den \'1\' alarak sonu \'01\' olanlardır; C\'den sonra yeni bit gelirse son iki bit değiştiğinden B veya A\'ya dönülür.'),
  ('Myhill-Nerode teoremine göre bir L dilinin düzenli olabilmesi için gerek ve yeter koşul nedir?', 'L tarafından oluşturulan ayırt edilemezlik eşdeğerlik bağıntısının denklik sınıflarının sayısının sonlu olması', ['Dil içindeki en uzun dizgenin karakter sayısının alfabenin karesinden küçük olması', 'Dildeki tüm dizgelerin baştan ve sondan okunduğunda simetrik yapı göstermesi', 'Gramer kurallarında hiçbir özyinelemeli üretim satırının yer almaması'], 'Myhill-Nerode teoremi, denklik sınıflarının sayısının sonlu olmasının dilin düzenliliğine denk olduğunu ve bu sayının en küçük DFA\'nın durum sayısını verdiğini söyler.'),
  ('Onluk tabanda (Σ = {0,1,...,9}) 5\'e kalansız bölünen pozitif tam sayıları tanıyan en küçük DFA\'nın 3\'e kalansız bölünenleri tanıyan DFA\'dan daha az durum gerektirmesinin nedeni nedir?', '5\'e bölünebilme yalnızca son rakamın 0 veya 5 olmasına bağlıyken 3\'e bölünebilme tüm basamakların toplam kalanını izlemeyi gerektirir', ['5 asal bir sayı olduğu için sonlu otomatlarda her zaman tek durumla temsil edilir', 'Onluk tabanda 5\'in katları çift sayı olduğundan yarısı otomatik olarak elenir', '3\'e bölünebilme dili düzenli olmadığı için sonsuz durum gerektirir'], '10 mod 5 = 0 olduğundan önceki basamakların kalan katkısı sıfırlanır; yalnızca \'son rakam {0,5} mi değil mi\' bilgisi (başlangıç/kabul ayrımıyla 2 durum) yeterlidir, 3\'e bölünme ise 3 kalan durumu ister.'),
  ('Neden tek yığınlı bir otomat (PDA) \'a^n b^n\' dilini kolayca tanırken, üç grubun eşit olduğu \'a^n b^n c^n\' (n >= 0) dilini tanıyamaz?', 'Yığına itilen \'a\' sembolleri \'b\'leri saymak için çekilip tüketildiğinde, \'c\'leri karşılaştıracak sayı bilgisi yığında kalmaz', ['Yığınlı otomatların alfabesinde en fazla iki farklı harf tanımlanmasına izin verilir', 'Üçüncü harf grubu geldiğinde sonlu durum denetleyicisi başlangıç durumuna kilitlenir', '\'c\' sembolü yığın tabanı işareti olarak ayrıldığı için girdi olarak okunamaz'], 'LIFO yığında eşleştirme yıkıcıdır (pop işlemi elemanı siler): \'a\'lar yığına atılıp \'b\'lerle eşleştirilerek boşaltılınca n değeri kaybolur; \'a^n b^n c^n\' bağlama duyarlıdır.'),
  ('İki farklı DFA olan M1 ve M2\'nin aynı dili tanıyıp tanımadığına (L(M1) = L(M2) eşdeğerlik problemi) karar veren bir algoritma var mıdır?', 'Evet, karar verilebilirdir; örneğin simetrik fark otomatının boş olup olmadığı veya minimize edilmiş DFA\'ların izomorfizmi denetlenebilir', ['Hayır; Alan Turing\'in Durma Problemi gereği iki otomatın eşdeğerliği hiçbir zaman kanıtlanamaz', 'Yalnızca sonlu sayıda dizge kabul eden otomatlar için karar verilebilir, döngülü olanlarda imkânsızdır', 'Ancak her iki otomatın durum sayıları birbirine tam olarak eşitse karar verilebilir'], 'Turing makinelerinin aksine DFA\'larda eşdeğerlik problemi tamamen karar verilebilirdir: her düzenli dilin tek (izomorfizma farkıyla benzersiz) bir minimum DFA\'sı vardır.'),
  ('Bir DFA\'nın kabul ettiği dilin SONSUZ sayıda dizge içerip içermediği grafiksel olarak nasıl anlaşılır?', 'Başlangıç durumundan ulaşılabilen ve kendisinden de en az bir kabul durumuna ulaşılabilen bir döngü (cycle) varsa dil sonsuzdur', ['Otomat diyagramında herhangi bir yerde öz-döngü (örneğin tuzak durumunda) bulunması dili sonsuz yapmaya yeter', 'Kabul durumlarının sayısı başlangıç dışındaki durumların sayısından fazlaysa dil sonsuzdur', 'Girdi alfabesinde en az iki sembol varsa her DFA zorunlu olarak sonsuz dil üretir'], 'Tuzak durumundaki döngü veya erişilemez döngüler kabul edilen dizge üretmez; döngünün hem başlangıçtan erişilebilir (accessible) hem de kabule ulaşabilir (co-accessible) bir yol üzerinde olması gerekir.'),
  ('İkili bir dizgede \'01\' alt dizgesinin geçiş sayısı ile \'10\' alt dizgesinin geçiş sayısının her zaman en fazla 1 fark edebilmesi (|#(01) - #(10)| <= 1) hangi şaşırtıcı sonucu doğurur?', '\'#(01) = #(10)\' koşulunu sağlayan ikili dizgeler dili sınırsız sayaç gerektirmeden düzenli bir dildir', ['Bu dil iki ayrı alt dizgeyi saydığı için yığınlı otomatla bile tanınamayan bağlama duyarlı bir dildir', 'Yalnızca içinde hiç \'0\' bulunmayan dizgeler bu eşitliği sağlayabilir', 'Söz konusu dili tanımak için dizge uzunluğunun karesi kadar duruma sahip DFA gerekir'], '0 ve 1 blokları almaşık değiştiğinden \'0\'dan \'1\'e geçiş sayısı ile \'1\'den \'0\'a geçiş sayısı ancak başlangıç ve bitiş karakterleri aynıysa (boş dizge ve tek harfliler dahil) tam eşit olur; bu da tamamen düzenlidir!'),
  ('Üç bitlik gri kod (Gray code) sayacı olarak çalışan bir sonlu durum makinesinde ardışık her durum geçişinde durum kodlamasının yalnızca tek bir bitinin değişmesi neden tercih edilir?', 'Birden fazla bitin aynı anda değişmesi sırasında oluşan geçici yarış hatalarını (glitch / hazard) önlemek için', ['Üç bitlik bellekle 8 yerine 16 farklı durumu aynı anda kodlayabilmek için', 'Girdi alfabesindeki karakter sayısını yarıya indirerek derleme süresini kısaltmak için', 'Tuzak durumlarını otomatik olarak kabul durumuna dönüştürmek için'], 'Donanımsal FSM durum atamasında (state encoding) komşu durumlara Gray kodu verilmesi, kapı gecikmeleri yüzünden yanlış ara durumların tetiklenmesini engeller.'),
  ('Σ = {a} gibi tek harfli (unary) bir alfabede tanımlanan sonlu bir otomatın kabul durumları ve döngü yapısı, kabul edilen dizge uzunlukları kümesi hakkında ne söyler?', 'Kabul edilen uzunluklar bir noktadan sonra aritmetik dizilerin sonlu birleşimi biçiminde periyodik olmak zorundadır', ['Tek harfli alfabede yalnızca asal sayı uzunluğundaki {a^p | p asal} dili bile DFA ile tanınabilir', 'Tek harfli alfabedeki tüm diller döngü içermediğinden yalnızca sonlu sayıda dizge barındırır', 'Tek harfli NFA\'lar çok harfli NFA\'ların aksine hiçbir zaman DFA\'ya dönüştürülemez'], 'Tek harfli DFA\'da her durumdan tek bir ok çıkar (rho-şekilli/kement yapı: bir kuyruk ve tek bir döngü); bu yüzden asal uzunluklar {a^p} veya tam kareler {a^(n^2)} düzenli olamaz.'),
  ('Saf ağaç özyinelemeli \'fib(n) = fib(n-1) + fib(n-2)\' algoritmasının zaman karmaşıklığı ile çağrı yığınında aynı anda kapladığı maksimum bellek karmaşıklığı nedir?', 'O(2^n) üstel zaman ve O(n) doğrusal yığın belleği', ['O(2^n) üstel zaman ve O(2^n) üstel yığın belleği', 'O(n^2) karesel zaman ve O(log n) logaritmik yığın belleği', 'O(n) doğrusal zaman ve O(n) doğrusal yığın belleği'], 'Çağrı ağacının toplam düğüm sayısı üstel (~φ^n, O(2^n)) olduğundan zaman üsteldir; ancak dallar derinlik öncelikli sırayla çalışıp bittiğinde yığından silindiği için anlık yığın derinliği en fazla n olur!'),
  ('McCarthy 91 fonksiyonu M(n): \'n > 100 ise n - 10 döndür; değilse M(M(n + 11)) döndür\' biçiminde tanımlanmıştır. Buna göre M(99) çağrısının sonucu kaçtır?', '91', ['89', '100', '99'], 'M(99) = M(M(110)) = M(100) = M(M(111)) = M(101) = 101 - 10 = 91 olur (n <= 101 için her zaman 91 döner).'),
  ('Özyinelemeli Hızlı Üs Alma (Exponentiation by Squaring) algoritması x^n değerini n çift iken (x^(n/2))^2 ile hesaplar. Bir öğrenci bunu \'return usAl(x, n/2) * usAl(x, n/2);\' şeklinde yazarsa zaman karmaşıklığına ne olur?', 'Aynı alt çağrıyı iki kez yaptığı için O(log n) avantajını kaybedip yeniden O(n) karmaşıklığa düşer', ['Derleyici çarpma operatörünü otomatik birleştirdiği için O(1) sabit sürede tamamlanır', 'Çift sayılarda sonsuz özyinelemeye girerek yığın taşması hatası fırlatır', 'Üs değerini iki katına çıkararak yanlışlıkla x^(2n) sonucunu hesaplar'], 'T(n) = 2·T(n/2) + O(1) bağıntısının çözümü Ana Teorem (Master Theorem) gereği O(n)\'dir; O(log n) için sonuç yerel değişkende bir kez hesaplanıp kendisiyle çarpılmalıdır!'),
  ('Ana Teorem (Master Theorem) kullanılarak T(n) = 4·T(n/2) + O(n) özyineleme bağıntısı çözüldüğünde zaman karmaşıklığı ne bulunur?', 'O(n^2)', ['O(n log n)', 'O(n^4)', 'O(n)'], 'a = 4, b = 2 için n^(log_b a) = n^(log_2 4) = n^2 olur; f(n) = O(n) bu değerden polinomik olarak küçük olduğundan yaprak maliyeti baskındır ve sonuç O(n^2) çıkar.'),
  ('Hızlı Sıralama (Quicksort) algoritmasında her adımda dizinin en küçük veya en büyük elemanı pivot seçilirse özyineleme derinliği ve ek yığın belleği karmaşıklığı ne olur?', 'O(n) derinliğe ulaşarak derin dizilerde yığın taşması riski doğurur', ['Her zaman O(log n) dengeli derinlikte kalarak sabit bellek tüketir', 'Özyineleme ilk adımda sonlanarak diziyi tek geçişte sıralar', 'Çağrı yığını yerine yalnızca işlemci yazmaçlarını kullanarak O(1) kalır'], 'Dengesiz bölünmede T(n) = T(n-1) + O(n) oluşur ve özyineleme derinliği log n yerine n olur; bunu önlemek için önce küçük parçaya özyineleme yapıp büyük parçada kuyruk çağrısı kullanılır.'),
  ('f(n) fonksiyonu \'eğer n <= 1 ise return 1; değilse return f(n - 1) + f(n - 1);\' şeklinde tanımlanmıştır. Bu fonksiyonun ürettiği değer ve çalışma zamanı karmaşıklığı hakkında hangisi doğrudur?', '2^(n-1) değerini hesaplar ve iki ayrı özyinelemeli kol açtığı için O(2^n) zamanda çalışır', ['2^(n-1) değerini hesaplar ve aynı parametreyle çağrıldığı için O(n) zamanda çalışır', '2n değerini hesaplar ve doğrusal derinlikte olduğu için O(n) zamanda çalışır', 'n^2 değerini hesaplar ve ikili ağaç kurduğu için O(n log n) zamanda çalışır'], '\'2 * f(n - 1)\' yazılsaydı O(n) zamanda çalışırdı; ancak \'f(n - 1) + f(n - 1)\' yazıldığında derleyici saf fonksiyon garantisi olmadan iki çağrıyı da ayrı ayrı yürütür ve T(n) = 2T(n-1) + 1 -> O(2^n) olur!'),
  ('Tek yönlü bir bağlı listenin (singly linked list) elemanlarını bağlantı yönlerini ters çevirerek yerinde (in-place) tersleyen özyinelemeli \'tersle(bas)\' fonksiyonunda \'yeniBas = tersle(bas.sonraki)\' satırından sonra mevcut düğümü sona bağlamak için hangi atamalar yapılmalıdır?', 'bas.sonraki.sonraki = bas; ve bas.sonraki = null;', ['bas = bas.sonraki; ve yeniBas.sonraki = bas;', 'yeniBas.sonraki = bas.sonraki; ve bas = null;', 'bas.sonraki = yeniBas; ve yeniBas.sonraki = null;'], 'Alt liste terslendiğinde \'bas.sonraki\' düğümü artık terslenmiş alt listenin en son elemanıdır; onun \'sonraki\' işaretçisi \'bas\'a yönlendirilir ve döngü oluşmaması için \'bas.sonraki = null\' yapılır.'),
  ('Python gibi bazı yüksek seviyeli dillerde kuyruk çağrısı eniyilemesi (TCO) kasıtlı olarak uygulanmayıp özyineleme derinlik sınırının (örneğin ~1000 çerçeve) varsayılan olarak korunmasının tasarım gerekçesi nedir?', 'Hata ayıklama sırasında tam çağrı yığını izini (stack trace) kaybetmemek ve sonsuz özyinelemeyi erken yakalamak', ['Python yorumlayıcısının yerel değişkenleri çağrı yığını yerine yalnızca CPU önbelleğinde tutması', 'Kuyruk özyinelemeli fonksiyonların matematiksel olarak döngülere dönüştürülmesinin imkânsız olması', 'Dinamik tipli dillerde fonksiyonların kendilerini çağırmasının bellek sızıntısı yaratması'], 'TCO ara çerçeveleri sildiği için bir hata oluştuğunda hangi çağrı zinciriyle oraya gelindiğini gösteren stack trace kısalır; Guido van Rossum bu nedenle açık döngüleri ve tam izlemeyi tercih etmiştir.'),
  ('Collatz (3n + 1) dizisini hesaplayan \'collatz(n): n == 1 ise dur; n çiftse collatz(n/2), tekse collatz(3n+1)\' fonksiyonu neden klasik özyineleme kuramında sıra dışı bir örnektir?', 'Her adımda girdi kesin olarak küçülmediği halde tüm pozitif tam sayılar için durup durmadığı matematiksel olarak hâlâ kanıtlanamamıştır', ['Taban durumu hiç bulunmadığı halde her girdi için tam olarak 3 adımda sonlandığı kanıtlanmıştır', 'Yalnızca asal sayılar verildiğinde kuyruk özyinelemesi olmadan sabit O(1) sürede çalışır', 'Çağrı yığını yerine yalnızca ikili arama ağacı kullanarak kendi kendini derler'], 'Genelde özyinelemenin sonlanmasını (termination) kanıtlamak için kesin azalan bir ölçü (variant) gösterilir; 3n+1 adımında sayı büyüdüğü için Collatz sanısının genel sonlanması açık bir matematik problemidir.'),
  ('Dinamik programlamadaki \'Yukarıdan Aşağıya (Top-Down / Memoization)\' yaklaşımı ile \'Aşağıdan Yukarıya (Bottom-Up / Tabulation)\' yaklaşımı karşılaştırıldığında Yukarıdan Aşağıya özyinelemeli yöntemin öne çıkan avantajı nedir?', 'Tüm alt problem tablosunu doldurmak yerine yalnızca ana hedef için gerçekten ihtiyaç duyulan alt problemleri çözmesi', ['Hiçbir zaman çağrı yığını çerçevesi kullanmadığı için yığın taşması riskini tamamen sıfırlaması', 'Önbellek tablosuna hiç ihtiyaç duymadan her zaman O(1) ek bellekle çalışması', 'Derleme zamanında tüm döngüleri kaldırarak makine kodu boyutunu yarıya indirmesi'], 'Bottom-Up tüm tabloyu sırayla doldururken (stack overflow riski yoktur), Top-Down özyinelemeli memoization yalnızca erişilen alt durumları hesaplar ama derin çağrılarda yığın kullanır.'),
  ('Bağlamdan bağımsız bir gramerde \'İfade -> İfade + Terim | Terim\' gibi kuralın sağ tarafının en solunda aynı değişkenin kendi adıyla başlamasına ne denir ve hangi özyinelemeli ayrıştırıcıyı sonsuz döngüye sokar?', 'Sol özyineleme (left recursion); yukarıdan aşağıya özyinelemeli iniş (recursive descent) ayrıştırıcısını sonsuz çağrıya sokar', ['Sağ özyineleme (right recursion); aşağıdan yukarıya LR yığın ayrıştırıcısını sonsuz döngüye sokar', 'Kuyruk özyinelemesi (tail recursion); sözcüksel analizcinin DFA tablosunu kilitler', 'Karşılıklı belirsizlik (mutual ambiguity); makine kodu üretecinin yazmaçlarını taşırır'], 'Özyinelemeli iniş ayrıştırıcısında \'ifadeOku()\' fonksiyonu hiçbir girdi jetonu tüketmeden ilk satırda tekrar \'ifadeOku()\' çağıracağı için sol özyineleme yığın taşması yaratır.'),
  ('Bir \'Para Üstü Verme\' probleminde verilen madeni para kümesiyle T tutarını oluşturmanın minimum madeni para sayısını bulan özyinelemeli bağıntı (önbellekli) hangisidir?', 'T == 0 ise 0; değilse T >= c olan tüm c paraları üzerinden 1 + min(enAzPara(T - c))', ['T == 0 ise 1; değilse tüm c paraları üzerinden toplam(enAzPara(T - c))', 'T <= 0 ise T; değilse yalnızca en büyük c parası seçilerek 1 + enAzPara(T % c)', 'T == 1 ise 0; değilse enAzPara(T / 2) + enAzPara(T / 2)'], '{1, 3, 4} ve T = 6 gibi durumlarda açgözlü (yalnız en büyük parayı seçme: 4+1+1=3 para) yanıltıcıdır; özyinelemeli min(enAzPara(T - c)) + 1 tüm seçenekleri deneyerek 3+3=2 parayı bulur.'),
  ('Trampolin (trampolining) tekniği, kuyruk çağrısı eniyilemesini (TCO) doğal olarak desteklemeyen JavaScript veya Python gibi dillerde derin özyinelemeyi yığın taşırmadan çalıştırmak için nasıl bir yol izler?', 'Fonksiyon doğrudan kendini çağırmak yerine bir sonraki adımı sarmalayan adsız bir fonksiyon (thunk) döndürür ve dış döngü bunu çağırır', ['İşletim sisteminden çalışma zamanında 64 GB sanal yığın belleği talep ederek sınırı aşar', 'Özyinelemeli fonksiyonun kaynak kodunu metin olarak okuyup düzenli ifadeyle C diline çevirir', 'Her 100 çağrıda bir programı uyku moduna alarak çöp toplayıcının yığını silmesini bekler'], 'Trampolin döngüsü \'while (callable(sonuc)): sonuc = sonuc()\' mantığıyla çalışır; her adım hemen geri dönüp bir sonraki çağrıyı verdiğinden çağrı yığını derinliği 1\'i geçmez.'),
  ('Karatsuba çarpma algoritması n basamaklı iki büyük sayıyı çarparken klasik böl-ve-yönetteki 4 alt çarpım yerine cebirsel özdeşlikle 3 özyinelemeli alt çarpım yapar. Bu azaltma zaman karmaşıklığını O(n^2)\'den nereye indirir?', 'O(n^(log2 3)) yani yaklaşık O(n^1.585) düzeyine', ['O(n log n) doğrusal-logaritmik düzeye', 'O(n) doğrusal düzeye', 'O(log n) logaritmik düzeye'], 'T(n) = 3·T(n/2) + O(n) bağıntısı Ana Teorem ile çözüldüğünde özyineleme ağacındaki dal sayısının 4\'ten 3\'e düşmesi üssü log2(4)=2\'den log2(3)≈1.585\'e çeker.'),
  ('Yüzeysel kopyalama (shallow copy) yerine iç içe nesneler ve diziler barındıran karmaşık bir veri yapısının Derin Kopyasını (Deep Copy) alan özyinelemeli fonksiyon döngüsel referans içeren (örneğin A nesnesi B\'yi, B nesnesi tekrar A\'yı gösteren) bir çizgeyle karşılaşırsa ne yapmalıdır?', 'Kopyalanmış nesnelerin adres eşlemesini bir özet tablosunda (visited map) tutarak daha önce kopyalanan nesneye rastladığında mevcut kopyayı döndürmelidir', ['Yalnızca ilk iki seviyedeki nesneleri kopyalayıp daha derindeki tüm referansları null yapmalıdır', 'Döngüyü kırmak için nesnelerin içindeki tüm sayısal alanları sıfırlayarak devam etmelidir', 'Kuyruk özyinelemesi kullanarak sonsuz döngüyü ek tablo olmadan sonlandırmalıdır'], 'Ziyaret/kopya tablosu (memo map) tutulmazsa A -> B -> A döngüsü derin kopyalama sırasında sonsuz özyinelemeye girip Stack Overflow hatası verir.'),
  ('Matematikte üs alma operatörü \'^\' geleneksel olarak SAĞDAN birleşmelidir (yani 2 ^ 3 ^ 2 = 2 ^ (3 ^ 2) = 2 ^ 9 = 512). Buna göre \'2 ^ 3 ^ 2\' ifadesinin doğru RPN gösterimi hangisidir?', '2 3 2 ^ ^', ['2 3 ^ 2 ^', '^ ^ 2 3 2', '2 ^ 3 2 ^'], 'Önce sağdaki \'3 ^ 2\' hesaplanmalı (\'3 2 ^\' = 9), ardından 2 tabanına uygulanmalıdır: \'2 3 2 ^ ^\' -> 2^9 = 512 (\'2 3 ^ 2 ^\' olsaydı 8^2 = 64 çıkardı).'),
  ('Manevra İstasyonu (Shunting-yard) algoritmasında sıradaki operatör o1 okunduğunda, operatör yığınının tepesinde aynı önceliğe sahip o2 operatörü duruyorsa o1\'in soldan veya sağdan birleşmeli olması davranışı nasıl belirler?', 'o1 soldan birleşmeliyse tepedeki o2 çekilip çıktıya yazılır; o1 sağdan birleşmeliyse o2 çekilmeden o1 onun üzerine itilir', ['Her iki durumda da tepedeki o2 silinir ve yalnızca son gelen o1 çıktı kuyruğuna eklenir', 'o1 soldan birleşmeliyse o2 yığında kalır; sağdan birleşmeliyse tüm yığın boşaltılır', 'Eşit öncelikli iki operatör parantezsiz yan yana geldiğinde algoritma sözdizimi hatası verir'], '\'a - b - c\' (soldan) örneğinde ikinci \'-\' geldiğinde ilk \'-\' çıktıya atılır ki \'a b -\' önce yapılsın; \'a ^ b ^ c\' (sağdan) örneğinde ikinci \'^\' birincinin üstüne itilir ki \'b c ^\' önce yapılsın.'),
  ('Bir dizgenin yalnızca sayılar ve ikili operatörlerden oluşan geçerli bir RPN ifadesi olup olmadığını hesaplama yapmadan tek geçişte doğrulayan \'yığın derinliği sayacı (s = 0)\' kuralları hangisidir?', 'Sayıda s bir artırılır, ikili operatörde önce s >= 2 olduğu doğrulanıp s bir azaltılır; tüm ifade bittiğinde s == 1 olmalıdır', ['Sadece toplam sayı adedinin operatör adedinden bir fazla olması yeterlidir, ara adımlara bakılmaz', 'Sayıda s iki artırılır, operatörde s iki azaltılır; ifade sonunda s == 0 olmalıdır', 'Operatör geldiğinde s artırılır, sayı geldiğinde s azaltılır; ara adımlarda s negatif olabilir'], 'Yalnızca toplam adetlere bakmak \'+ 3 4\' gibi geçersiz sıralamaları yakalayamaz! Örneğin \'+ 3 4\' için N=2, M=1\'dir ama ilk adımda s < 2 olduğundan yığın alt taşması (stack underflow) olur.'),
  ('Polonya Gösterimi (Prefix / Önek Gösterimi, örneğin \'+ 3 * 4 5\') parantezsiz olarak tek bir yığınla doğrudan hesaplanmak istendiğinde jetonlar hangi yönde taranırsa en yalın algoritma elde edilir?', 'Sağdan sola doğru taranır; sayılar yığına itilir, operatör geldiğinde yığından çekilen ilk eleman sol, ikinci eleman sağ işlenen olur', ['Soldan sağa doğru taranır; operatörler atlanır ve yalnızca en sondaki iki sayı toplanır', 'Ortadan uçlara doğru taranır; her operatör için iki ayrı kuyruk veri yapısı açılır', 'Önek ifadeler yığınla çözülemediği için önce zorunlu olarak içtakı biçimine çevrilir'], 'Önek ifade sağdan sola okunduğunda RPN\'in ayna görüntüsü gibi davranır; üstelik sağdan sola itildiği için tepedeki ilk çekilen eleman doğrudan \'sol\' işlenen (a op b) olur!'),
  ('Neden bir İkili İfade Ağacında Son-sıralı (Post-order / RPN) dolaşma çıktısı ağacı tek bir biçimde geri kurmaya yeterken, parantezsiz İç-sıralı (In-order) çıktı ağacı geri kurmaya yetmez?', 'Parantezsiz iç-sıralı çıktıda hangi operatörün kök, hangisinin alt düğüm olduğu bilgisi kaybolur (örneğin \'(3+4)*5\' ve \'3+(4*5)\' ikisi de \'3 + 4 * 5\' verir)', ['İç-sıralı dolaşma yaprak düğümlerdeki sayıların yarısını atlayarak yalnızca operatörleri yazdırır', 'Son-sıralı dolaşmada her düğümün bellek adresi de çıktı dizgesinin yanına eklenir', 'İkili ifade ağaçlarında toplama ve çarpma operatörleri her zaman yaprak düğümlerde yer alır'], 'Farklı yapıdaki iki ifade ağacı parantezsiz In-order dolaşıldığında birebir aynı dizgeyi üretir; oysa Post-order (RPN) \'3 4 + 5 *\' ve \'3 4 5 * +\' olarak onları kesin ayırır.'),
  ('İçtakı ifadelerde \'-\' sembolünün hem ikili çıkarma (\'5 - 3\') hem de tekli (unary) negatif işaret (\'-3 + 5\' veya \'4 * -2\') olarak kullanılması Manevra İstasyonu algoritmasında nasıl çözülür?', 'Sözcüksel/bağlamsal kuralla tekli eksi ayırt edilip (örneğin \'u-\' veya \'~\' olarak) yüksek öncelikli ve sağdan birleşmeli tek işlenenli operatör yapılır', ['Tekli eksi işaretlerinin tamamı sözcüksel analiz sırasında silinerek sayılar mutlak değere çevrilir', 'Her eksi işaretinin soluna koşulsuz olarak sıfır (\'0\') eklendiği için \'5 - 3\' ifadesi \'5 0 - 3\' olur', 'Tekli operatörler RPN gösteriminde ifade edilemediği için bu tür girdiler derleyici tarafından reddedilir'], 'İfadenin en başında, \'(\' sonrasında veya başka bir operatörden hemen sonra gelen \'-\' tekli eksidir; RPN\'de farklı bir jetonla (ör. \'u-\') temsil edilip yığından 2 değil yalnızca 1 eleman çeker.'),
  ('Bir derleyici \'x = a + b * c\' atama deyimini RPN\'e \'x a b c * + =\' biçiminde dönüştürdüğünde, sol taraftaki \'x\' ile sağ taraftaki \'a, b, c\' değişkenlerinin yığına itilmesinde nasıl bir anlamsal fark vardır?', '\'x\' için değişkenin bellek adresi (l-value), \'a, b, c\' için ise değişkenlerin o anki değerleri (r-value) yığına itilir', ['Tüm değişkenlerin yalnızca ASCII isim dizgeleri yığına itilir ve \'=\' operatörü hepsini siler', '\'x\' yığına hiç itilmez, en son hesaplanan değer rastgele boş bir yazmaca yazılır', '\'a, b, c\' için bellek adresleri itilirken \'x\' için eski sayısal değeri itilir'], 'Atama operatörü \'=\' sağ işlenenin hesaplanmış değerini (r-value) alıp sol işlenenin gösterdiği bellek konumuna (l-value / adres) yazar.'),
  ('Derleyiciler \'(a + b) + (c + (d + e))\' gibi değişme ve birleşme özelliği olan ifadelerde kod üretirken daha derin olan alt ağacı (örneğin \'c + (d + e)\') neden önce hesaplamayı tercih eder (Sethi-Ullman algoritması)?', 'Ara sonuçları tutmak için gereken maksimum yığın derinliğini veya işlemci yazmacı sayısını en aza indirmek için', ['Toplama işleminin sayısal sonucunu tam sayı taşmasından tamamen korumak için', 'Değişkenlerin alfabetik sırasını tersine çevirerek önbellek boyutunu büyütmek için', 'Sözdizimi ağacındaki yaprak düğümlerin sayısını yarıya indirmek için'], 'Önce \'a+b\' hesaplanırsa sonucu 1 yazmaç/yığın hücresi işgal ederken sağdaki derin ağaç ek hücreler ister; önce derin kol hesaplanıp tek değere indirgenirse daha az yazmaç yetmektedir!'),
  ('Bir fonksiyon çağrısı olan \'max(3 + 4, 2 * 5)\' ifadesini Manevra İstasyonu algoritmasıyla RPN biçimine çevirirken virgül (\',\') ayırıcısının görevi nedir?', 'Solundaki argüman alt ifadesinin yığında bekleyen operatörlerini \'(\' işaretine kadar çıktıya boşaltmak (ancak \'(\' işaretini yığından silmemek)', ['Fonksiyon adını operatör yığınından silerek argüman sayısını sıfırlamak', 'Sağındaki ve solundaki sayıları birleştirerek ondalıklı kesirli sayı oluşturmak', 'Açılış parantezini yığından çekip atarak fonksiyon çağrısını erken sonlandırmak'], 'Virgül argüman ayırıcısıdır: birinci argümanın (\'3 + 4\' -> \'3 4 +\') operatörlerini \'(\' sınırına kadar tamamlatır ama fonksiyon kapanışına (\')\') kadar \'(\' yığında kalır; sonuç \'3 4 + 2 5 * max\' olur.'),
  ('Değişken sayıda argüman alabilen fonksiyonlar (örneğin \'toplam(1, 2)\' ile \'toplam(1, 2, 3, 4)\') RPN dizisine çevrildiğinde yığın değerlendiricisinin yığından kaç argüman çekeceğini bilmesi için jetona hangi bilgi eklenir?', 'Fonksiyon çağrısının o noktadaki argüman sayısı', ['Fonksiyonun kaynak koddaki satır ve sütun numarası', 'Argümanların veri boyutlarının onaltılık bellek özeti', 'Yığının başlangıçtaki boş kapasite bayt miktarı'], '\'+\' her zaman 2 eleman çeker ama değişken argümanlı fonksiyonlarda RPN jetonuna kaç argümanla çağrıldığı bilgisi (arity) iliştirilir veya çerçeve işaretçisi konur.'),
  ('RPN\'den içtakı (infix) ifadeye geri dönüştürme yapan bir algoritmada ne zaman alt ifadenin etrafına parantez eklemek ZORUNLUDUR?', 'Alt ifadenin kök operatörünün önceliği kendisini kapsayan üst operatörün önceliğinden daha düşük olduğunda', ['Yalnızca toplama ve çarpma dışındaki bölme işlemleriyle karşılaşıldığında', 'İfadedeki toplam değişken sayısı dörtten fazla olduğunda her ikili gruba', 'Hiçbir zaman gerekmez; alt dizgeleri boşlukla birleştirmek her zaman doğru ifadeyi verir'], 'Örneğin \'a b - c -\' için parantez gerekmez (\'a - b - c\'), ancak \'a b c - -\' için sağ alt ağacın kökü \'-\' üstteki \'-\' ile sağ kol çakışması yaşadığından \'a - (b - c)\' parantezi zorunludur!'),
  ('Kısa devre değerlendirmesi (short-circuit evaluation, örneğin \'x != 0 && 10 / x > 1\' ifadesinde x = 0 iken sağ tarafın hiç çalıştırılmaması) saf ve düz bir RPN hesaplayıcısında (\'x 0 != 10 x / 1 > &&\') neden sorun çıkarır?', 'Saf RPN soldan sağa tüm işlenenleri yığına hesaplayarak ittiği için \'&&\' görülmeden önce \'10 / 0\' bölmesi çalışıp hata verir', ['Mantıksal VE operatörü RPN gösteriminde her zaman ifadenin en başında yazılmak zorundadır', 'RPN yığınları tam sayılarla mantıksal doğruluk değerlerini aynı anda tutamaz', 'Sıfıra eşit olmama operatörü (\'!=\') üç işlenen beklediği için yığın eksik kalır'], 'Saf RPN hevesli (eager) değerlendirme yapar; derleyiciler kısa devre \'&&\', \'||\' ve \'?:\' operatörlerini düz RPN operatörü yerine koşullu sıçrama (branch/jump) etiketleriyle üretir!'),
  ('Yukarıdan aşağıya ayrıştırıcılardan olan LL(1) ile aşağıdan yukarıya ayrıştırıcılardan olan LR(1) kısaltmalarındaki ilk \'L\', ikinci harf (\'L\' veya \'R\') ve parantez içindeki \'1\' sırasıyla ne anlama gelir?', 'Girdiyi Soldan sağa okuma; LL\'de en Sol türetimi, LR\'de en Sağ türetimi tersinden üretme; 1 jetonluk ileriye bakış (lookahead) kullanma', ['Doğrusal Zaman (Linear); Düşük Bellek (Low) veya Rastgele Erişim (Random); 1 geçişli derleme yapma', 'Sözcüksel Katman (Lexical); Sol özyineleme veya Sağ özyineleme; 1 adet yığın belleği kullanma', 'Yerel Kapsam (Local); Bağlayıcı (Linker) veya Çalışma Zamanı (Runtime); 1 baytlık komut üretme'], 'LL(k): Left-to-right scan, Leftmost derivation, k lookahead tokens. LR(k): Left-to-right scan, Rightmost derivation in reverse, k lookahead tokens.'),
  ('Aşağıdan yukarıya çalışan Kaydır-İndirge (Shift-Reduce / LR) ayrıştırıcısında \'Kaydır (Shift)\' ve \'İndirge (Reduce)\' eylemleri ne yapar?', 'Kaydır sıradaki girdi jetonunu yığına iter; İndirge ise yığının tepesindeki sağ taraf dizisini gramer kuralının sol tarafındaki değişkene dönüştürür', ['Kaydır yığındaki tüm elemanları bir bit sola kaydırır; İndirge sembol tablosundaki kullanılmayan değişkenleri siler', 'Kaydır hatalı satırı atlayarak sonraki satıra geçer; İndirge sabit sayıları derleme zamanında toplar', 'Kaydır soyut ağacı makine koduna çevirir; İndirge makine kodunun dosya boyutunu sıkıştırır'], 'Shift-Reduce ayrıştırıcılar yığının tepesinde bir \'tutamak\' (handle, üretim kuralının sağ tarafı A -> β) oluşana kadar jetonları yığına kaydırır (shift), oluşunca β\'yı çekip A\'ya indirger (reduce).'),
  ('Modern derleyicilerde (LLVM, GCC, JVM JIT) kullanılan Statik Tek Atama (SSA - Static Single Assignment) ara kod biçiminin belirleyici kuralı nedir?', 'Ara koddaki her değişkenin metin üzerinde tam olarak bir kez atanması; yeniden atamalarda \'x1, x2\' gibi yeni sürüm adları ve dal birleşimlerinde Φ (phi) fonksiyonu kullanılması', ['Kaynak programdaki tüm değişkenlerin otomatik olarak \'const\' sabit yapılara dönüştürülüp döngülerin yasaklanması', 'Bir fonksiyonun tüm yerel değişkenlerinin tek bir 64 bitlik yazmaç içine sıkıştırılarak saklanması', 'Programdaki tüm global değişkenlerin derleme zamanında sıfır değeriyle başlatılması'], 'SSA formunda her değişken yalnız bir tanım noktasına sahip olduğundan \'kullanım-tanım zincirleri\' (use-def chains) apaçık hale gelir ve ölü kod eleme ile sabit yayılımı çok hızlanır.'),
  ('Derleyicinin Arka Uç (Back-End) aşamasında sınırsız sayıda geçici değişken içeren ara kodu işlemcinin sınırlı sayıdaki fiziksel yazmaçlarına (register) yerleştirme problemini Chaitin algoritması hangi çizge kuramı problemi olarak modeller?', 'Girişim çizgesi üzerinde K-Renklendirme (Graph Coloring) problemi', ['Ağırlıklı yönlü çizgede En Kısa Yol (Dijkstra) problemi', 'Ağ akış çizgesinde Maksimum Akış - Minimum Kesit problemi', 'İki parçalı çizgede Euler Turu bulma problemi'], 'Aynı anda canlı (live) olan iki değişken aynı yazmacı paylaşamaz (aralarına kenar çizilir); K fiziksel yazmaçla çakışmasız atama yapmak girişim çizgesini K renkle boyamaya eşdeğerdir.'),
  ('Yazmaç ataması (register allocation) sırasında aynı anda canlı olan değişkenlerin sayısı işlemcinin mevcut fiziksel yazmaç sayısını aştığında derleyici ne yapar?', 'Bazı değişkenleri çalışma zamanı yığınına (RAM belleğe) taşıyıp gerektiğinde geri yükleyen \'yazmaç dökümü\' (register spilling) kodları üretir', ['Kaynak koddaki fazla değişkenleri silerek derleme hatası fırlatır ve işlemi durdurur', 'Değişkenlerin veri tiplerini 64 bitten 8 bite düşürerek tek yazmaca sığdırır', 'Programı derlemekten vazgeçip doğrudan yorumlayıcı moduna geçiş yapar'], 'Fiziksel yazmaç yetmediğinde daha az kullanılan değişkenler bellekteki yığın çerçevesine dökülür (spill); bu işlem LOAD/STORE komutları eklediği için performansı düşürür.'),
  ('Derleyicinin kuyruk özyinelemesi eniyileştirmesi (tail-call optimization) uygulayabilmesi bellek yönetimi açısından hangi temel avantajı sağlar?', 'Çağrı yığını alanını O(n) yerine O(1) düzeyinde sabit tutması', ['Zaman karmaşıklığını üstel düzeyden logaritmik düzeye indirmesi', 'Taban durumu tanımlanmadan da fonksiyonun güvenli sonlanması', 'İkili özyinelemeli ağaçları ek bellek kullanmadan paralel çözmesi'], 'Kuyruk çağrısı eniyileştirmesi mevcut aktivasyon kaydını yeniden kullanarak yığın belleği tüketimini O(1) düzeyine indirir.'),
  ('Ackermann fonksiyonu A(0, n) = n + 1; m > 0 için A(m, 0) = A(m - 1, 1) ve m > 0, n > 0 için A(m, n) = A(m - 1, A(m, n - 1)) olarak tanımlıdır. A(2, 2) değeri kaçtır?', '7', ['5', '9', '6'], 'A(1, k) = k + 2 olduğundan A(2, 0)=A(1,1)=3, A(2, 1)=A(1,3)=5 ve A(2, 2)=A(1,5)=7 bulunur.'),
  ('McCarthy 91 fonksiyonu M(n): n > 100 ise n - 10, n <= 100 ise M(M(n + 11)) olarak tanımlanır. M(99) çağrısının döndürdüğü değer kaçtır?', '91', ['89', '100', '90'], 'M(99) = M(M(110)) = M(100) = M(M(111)) = M(101) = 91 olarak sonuçlanır.'),
  ('T(1) = 1 ve n > 1 için T(n) = 2 * T(n / 2) + n özyineleme bağıntısıyla çalışma süresi modellenen bir algoritmanın asimptotik zaman karmaşıklığı nedir?', 'O(n log n)', ['O(n)', 'O(n^2)', 'O(log n)'], 'Birleştirmeli sıralama ile aynı yapıdaki bu bağıntıda log2(n) derinliğin her düzeyinde toplam n iş yapıldığından karmaşıklık O(n log n) olur.'),
  ('Bir ikili ağacın düğüm sayısını say(kok) = (kok == BOS ise 0, değilse 1 + say(kok.sol) + say(kok.sag)) ile bulan fonksiyon N düğümlü çizgisel (dejenere) bir ağaçta çalıştırıldığında çağrı yığınının ulaştığı maksimum derinlik hangi mertebededir?', 'O(N)', ['O(log N)', 'O(1)', 'O(N^2)'], 'Her düğümün tek çocuklu olduğu dejenere bir ikili ağacın yüksekliği N olduğundan özyineleme yığını O(N) derinliğe ulaşır.'),
  ('f(0) = 0, f(1) = 1, f(2) = 2 ve n > 2 için f(n) = f(n - 1) + 2 * f(n - 2) - f(n - 3) olarak tanımlanmıştır. Buna göre f(5) çağrısının döndürdüğü değer kaçtır?', '13', ['7', '10', '15'], 'f(3)=2+2(1)-0=4, f(4)=4+2(2)-1=7 ve f(5)=7+2(4)-2=13 olarak hesaplanır.'),
  ('Ağaç üzerinde derinlik öncelikli arama (DFS) yaparken özyineleme yerine açık yığın kullanmanın üretim ortamındaki en kritik mühendislik gerekçesi nedir?', 'Çok derin girdilerde işletim sistemi çağrı yığını sınırını aşarak çökmesini önlemek', ['Ziyaret edilen düğüm sayısını yarıya indirerek zaman karmaşıklığını düşürmek', 'Ağaçtaki döngüleri ek ziyaret kümesi tutmadan kendiliğinden tespit edebilmek', 'Önbellek yerelliğini ortadan kaldırarak bellek erişimlerini rastgele hale getirmek'], 'İşletim sistemi çağrı yığını genellikle birkaç megabaytla sınırlıyken küme (heap) bellekte tutulan açık yığın çok daha büyük derinliklere güvenle büyüyebilir.'),
  ('g(n) prosedürü n > 0 için sırasıyla g(n - 1), ekranaYaz(n) ve tekrar g(n - 1) işlemlerini çalıştırmaktadır (n == 0 ise durmaktadır). g(3) çağrısının ürettiği çıktı dizisi nedir?', '1 2 1 3 1 2 1', ['3 2 1 1 2 3', '1 2 3 2 1', '1 1 2 1 1 3 1'], 'İkili ağaçta orta kök (in-order) gezinme sırasını izleyen bu yapı g(1)="1", g(2)="1 2 1" ve g(3)="1 2 1 3 1 2 1" çıktısını üretir.'),
  ('Üs alma işleci "^" sağdan sola birleşmeli (right-associative) bir işleçtir. Buna göre "2 ^ 3 ^ 2" infix ifadesinin doğru postfix karşılığı ve sayısal değeri nedir?', '2 3 2 ^ ^ ve 512', ['2 3 ^ 2 ^ ve 64', '2 3 2 ^ * ve 18', '2 2 3 ^ ^ ve 256'], 'Sağdan birleşme nedeniyle ifade 2 ^ (3 ^ 2) olarak gruplanır; postfix biçimi "2 3 2 ^ ^" ve değeri 2^9 = 512 olur.'),
  ('Çıkarma işleci soldan sağa birleşmelidir (left-associative). Buna göre "10 - 4 - 2" infix ifadesinin doğru postfix karşılığı ve sayısal sonucu nedir?', '10 4 - 2 - ve 4', ['10 4 2 - - ve 8', '- - 10 4 2 ve 8', '10 2 - 4 - ve 6'], 'Soldan birleşme gereği (10 - 4) - 2 = 4 olur; postfix karşılığı "10 4 - 2 -" biçimindedir ("10 4 2 - -" olsaydı 10 - (4 - 2) = 8 çıkardı).'),
  ('"6 2 3 + - 3 8 2 / + *" postfix ifadesi yığınla değerlendirilirken herhangi bir anda yığında aynı anda bulunan eleman sayısı en fazla kaç olur?', '4', ['2', '3', '5'], 'İzleme: [6], [6,2], [6,2,3] -> + ile [6,5] -> - ile [1] -> [1,3], [1,3,8], [1,3,8,2] (4 eleman) -> / ile [1,3,4] -> + ile [1,7] -> * ile [7]; maksimum derinlik 4 olur.'),
  ('Geçerli bir postfix ifadede yalnızca ikili (binary) işleçler ve tekil sayılar (işlenenler) kullanılmaktadır. İfadedeki toplam işlenen sayısı N ise toplam ikili işleç sayısı kaç olmak zorundadır?', 'N - 1', ['N', 'N + 1', '2N - 1'], 'Başlangıçta 0 olan yığın boyutu her işlenende 1 artar, her ikili işleçte 1 azalır (2 çekip 1 iter); sonunda yığında 1 sonuç kalması için N - (işleç sayısı) = 1 yani işleç sayısı N - 1 olmalıdır.'),
  ('Yalnızca sayılar ve ikili işleçlerden oluşan bir belirteç dizisinin geçerli bir postfix ifade olabilmesi için soldan sağa tarama boyunca yığın yüksekliği (eleman sayısı) hangi koşulu sağlamalıdır?', 'Hiçbir işleç adımında 2\'nin altına düşmemeli ve tarama bittiğinde tam olarak 1 olmalıdır', ['Tarama boyunca her zaman çift sayı olmalı ve tarama sonunda 0 değerine inmelidir', 'Hiçbir adımda toplam işleç sayısını aşmamalı ve sonunda işlenen sayısına eşit olmalıdır', 'Başlangıçta 1 olarak başlamalı ve her adımda monoton olarak artarak N değerine ulaşmalıdır'], 'Her ikili işleç yığından 2 eleman çekeceği için işlem anında en az 2 eleman bulunmalı, ifade tamamlandığında ise yığında tek bir nihai sonuç kalmalıdır.'),
  ('Bir ifade ağacı üzerinde orta-kök (in-order: sol, kök, sağ) gezinmesi yapılırken parantez eklenmezse hangi temel sorun ortaya çıkar?', 'İşlem önceliği bilgisi kaybolabileceği için orijinal ifadeyle eşdeğer olmayan belirsiz infix dizilim oluşabilir', ['İşlenenlerin kendi aralarındaki göreli sol-sağ sırası tamamen tersine döner', 'Ağaçtaki yaprak düğümler birden fazla kez çıktıya yazılarak ifade uzunluğu ikiye katlanır', 'Değişme özelliği olan toplama ve çarpma işlemleri çıkarma işlemine dönüşür'], 'Örneğin (3+4)*5 ağacında parantezsiz in-order gezinme "3 + 4 * 5" üretir ki bu da farklı bir işlem önceliğine yol açar.'),
  ('"- / * 12 + 2 3 6 4" prefix ifadesinin tam sayı işlemleriyle değerlendirilmesi sonucunda kaç elde edilir?', '6', ['10', '2', '14'], 'İçten dışa doğru: (+ 2 3) = 5, (* 12 5) = 60, (/ 60 6) = 10 ve (- 10 4) = 6 bulunur.'),
  ('Tekli eksi (unary minus, örneğin ~x ile gösterilsin) ve ikili çıkarma (-) işleçlerini birlikte içeren "5 ~ 3 - ~" postfix ifadesinin sayısal sonucu kaçtır?', '8', ['-8', '2', '-2'], 'Adım adım: 5 -> ~ ile [-5] -> 3 itilir [-5, 3] -> ikili - ile (-5 - 3 = -8) [-8] -> ~ ile -(-8) = 8 elde edilir.'),
  ('"a b + c * d e - /" postfix ifadesini kök düğümü bulunan bir ifade ağacına dönüştürdüğümüzde kök düğümde ve kökün sol çocuğunda sırasıyla hangi işleçler yer alır?', 'Kökte "/" ve sol çocukta "*"', ['Kökte "*" ve sol çocukta "+"', 'Kökte "-" ve sol çocukta "/"', 'Kökte "/" ve sol çocukta "-"'], 'İfade ((a + b) * c) / (d - e) biçimindedir; en dış işlem "/" kökte, sol alt ifade "(a + b) * c"nin ana işleci "*" sol çocukta, "-" ise sağ çocukta bulunur.'),
  ('E -> E + E | E * E | sayi grameri neden belirsiz (ambiguous) bir gramerdir?', '2 + 3 * 4 gibi bir ifade için hem toplamanın hem çarpmanın üstte olduğu iki farklı ayrıştırma ağacı üretebildiği için', ['Yalnızca tek basamaklı sayıları kabul edip çok basamaklı sayıları reddettiği için', 'Çıkarma ve bölme işleçlerini üretim kuralları arasında barındırmadığı için', 'Boş dizgi (epsilon) üretimini başlangıç simgesinde doğrudan kullanmadığı için'], 'Öncelik ve birleşme yönü katmanlandırılmadığı için 2 + 3 * 4 ifadesi (2+3)*4 veya 2+(3*4) ağaçlarıyla iki farklı biçimde türetilebilir.'),
  ('E -> E + T | T, T -> T * F | F, F -> ( E ) | id gramer yapısında çarpmanın toplamadan daha yüksek önceliğe sahip olmasını hangi yapısal özellik sağlar?', 'Çarpma kuralının toplama kuralına göre başlangıç simgesinden daha alt katmanda (yapraklara daha yakın) tanımlanması', ['Toplama simgesinin ASCII tablosunda çarpma simgesinden daha büyük bir sayısal koda sahip olması', 'Parantez kuralının yalnızca başlangıç simgesi E üzerinde doğrudan uygulanabilmesi', 'Üretim kurallarının tamamının sağdan özyinelemeli biçimde yazılmış olması'], 'Ayrıştırma ağacında yapraklara daha yakın katmanda yer alan T -> T * F kuralı daha önce bağlanarak daha yüksek öncelik kazanır.'),
  ('Bağlamdan bağımsız dilleri tanıyan (kabul eden) soyut hesaplama otomatı modeli aşağıdakilerden hangisidir?', 'Yığınlı otomat (Pushdown Automaton - PDA)', ['Deterministik sonlu durum otomatı (DFA)', 'Doğrusal sınırlı otomat (LBA)', 'Kayıt tabanlı sonlu sayaç devresi'], 'Düzenli diller sonlu otomatlarla tanınırken, bağlamdan bağımsız dilleri tanımak için ek bir yığın belleğe sahip yığınlı otomat (PDA) gerekir.'),
  ('Bir bağlamdan bağımsız gramerin tüm üretim kurallarının A -> BC veya A -> a (başlangıç için gerekirse S -> ε) biçiminde kısıtlandığı standart forma ne ad verilir?', 'Chomsky Normal Formu (CNF)', ['Greibach Normal Formu (GNF)', 'Genişletilmiş Backus-Naur Formu (EBNF)', 'Statik Tekil Atama Formu (SSA)'], 'Sağ tarafta ya iki değişken (BC) ya da tek bir uçbirim simge (a) bulunmasını şart koşan standart biçim Chomsky Normal Formudur.'),
  ('Chomsky Normal Formundaki bir bağlamdan bağımsız gramer için n uzunluğundaki bir dizginin dile ait olup olmadığını dinamik programlamayla O(n^3) zamanda belirleyen algoritma hangisidir?', 'CYK (Cocke-Younger-Kasami) algoritması', ['Dijkstra Shunting-yard algoritması', 'Boyer-Moore dizgi arama algoritması', 'Kruskal minimum yayılan ağaç algoritması'], 'CYK algoritması alt dizgileri dinamik programlama tablosuyla birleştirerek O(n^3) sürede CFG üyelik ve ayrıştırma testi yapar.'),
  ('L = { a^n b^n c^n | n >= 1 } dilinin Chomsky hiyerarşisindeki konumu hakkında aşağıdakilerden hangisi doğrudur?', 'Bağlamdan bağımsız değildir; bağlama duyarlı (Tip-1) bir dildir', ['Düzenli (Tip-3) bir dildir ve sonlu durum otomatıyla tanınabilir', 'Bağlamdan bağımsız (Tip-2) bir dildir ve tek yığınla sayılabilir', 'Hiçbir Turing makinesi tarafından karar verilemeyen bir dildir'], 'Tek bir yığın a ile b sayısını eşleştirdiğinde yığın boşalır ve c sayısını doğrulayamaz; bu dil bağlamdan bağımsız değil, bağlama duyarlıdır.'),
  ('Derleyici kuramında LL(1) ve LR(1) kısaltmalarındaki ilk "L" harfi ile ikinci harf olan "L" veya "R" sırasıyla neyi ifade eder?', 'İlk L girdinin soldan sağa taranmasını; ikinci harf ise en soldan (L) türetme veya en sağdan (R) tersine türetme yapıldığını', ['İlk L yerel (local) değişkenleri; ikinci harf ise doğrusal (linear) veya özyinelemeli (recursive) belleği', 'İlk L sözcüksel (lexical) aşamayı; ikinci harf ise okuma (read) veya yükleme (load) işlemini', 'İlk L döngü (loop) sayısını; ikinci harf ise yazmaç (register) veya önbellek atamasını'], 'LL(k): Left-to-right tarama, Leftmost türetme; LR(k): Left-to-right tarama, ters sırada Rightmost türetme (kaydır-indirge) anlamına gelir.'),
  ('Alttan yukarı (bottom-up / LR) çalışan bir kaydır-indirge (shift-reduce) ayrıştırıcısında "indirge" (reduce) adımı tam olarak ne yapar?', 'Yığının tepesindeki simge dizisini bir üretim kuralının sağ tarafıyla eşleştirip kuralın sol tarafındaki uçbirim olmayan simgeyle değiştirir', ['Girdi akışındaki sıradaki belirteci okuyarak doğrudan ayrıştırma yığınının en üstüne iter', 'Gramerdeki kullanılmayan tüm üretim kurallarını silerek ayrıştırma tablosunu küçültür', 'Sözdizimi hatası oluştuğunda noktalı virgüle kadar olan tüm belirteçleri atlayıp kurtarma yapar'], 'Shift adımı belirteci yığına iterken, Reduce adımı yığın tepesindeki tutamacı (handle) kuralın sol tarafındaki değişkene indirger.'),
  ('Statik tip denetiminin dinamik tip denetimine kıyasla yazılım mühendisliği ve başarım açısından sağladığı iki temel kazanım nedir?', 'Tür hatalarını üretim öncesi derleme aşamasında yakalaması ve çalışma zamanındaki tür etiketi denetimi yükünü azaltması', ['Kaynak kodun hiç derlenmeden doğrudan metin olarak işlemci tarafından yürütülmesini sağlaması', 'Bellek sızıntılarını ve sonsuz döngüleri %100 kesinlikle tüm programlar için karar verilebilir kılması', 'Derleme süresini sıfıra indirerek sözdizimi çözümleyicisine olan ihtiyacı tamamen ortadan kaldırması'], 'Statik tip denetimi tip uyuşmazlıklarını erken yakalar ve derleyicinin çalışma zamanı tip kontrolleri olmadan doğrudan makine komutu üretmesine olanak tanır.'),
  ('Derleyici ara kodlarında her değişkene yaşam süresi boyunca yalnızca tek bir kez değer atanmasını zorunlu kılan ve veri akışı eniyileştirmelerini büyük ölçüde kolaylaştıran ara temsil biçimi nedir?', 'Statik Tekil Atama (SSA - Static Single Assignment) formu', ['Ters Lehçe Yığın Formu', 'Genişletilmiş Backus-Naur Formu', 'Bağlamdan Bağımsız Chomsky Formu'], 'SSA formunda her yeni atama x1, x2 gibi yeni bir sürüm adı alır ve kontrol akışı birleşimlerinde phi (φ) fonksiyonları kullanılır.'),
  ('Fonksiyon satır içi açma (inlining) ve döngü açma (loop unrolling) eniyileştirmeleri aşırı uygulandığında başarımı beklenenin aksine düşürebilmesinin temel donanımsal nedeni nedir?', 'Üretilen makine kodu boyutunun şişerek işlemci komut önbelleği (I-cache) ıskalarını artırması', ['İşlemcinin aritmetik mantık biriminin (ALU) toplama yeteneğini devre dışı bırakması', 'Kaynak koddaki değişkenlerin statik tiplerini dinamik tiplere dönüştürmesi', 'İşletim sisteminin sanal bellek sayfalama mekanizmasını tamamen kapatması'], 'Kod boyutu aşırı büyüdüğünde L1 komut önbelleğine sığmaz ve bellekten komut getirme gecikmeleri (cache miss) hız kazancını yok edebilir.'),
  ('Derleyicinin kod üretimi aşamasında çok sayıdaki geçici değişkeni işlemcinin sınırlı sayıdaki fiziksel yazmacına (register) atamak için değişken çakışmalarını çizge renklendirme (graph coloring) problemi olarak çözdüğü aşama hangisidir?', 'Yazmaç tahsisi (register allocation)', ['Sözcüksel tarama (lexical scanning)', 'Sol çarpanlara ayırma (left factoring)', 'Tür çıkarımı (type inference)'], 'Aynı anda canlı (live) olan değişkenler arasında kenar kurulan girişim çizgesinin k renkle boyanması klasik yazmaç tahsisi yöntemidir.'),
  ('Fiziksel yazmaç sayısı aynı anda canlı olan değişkenlerin sayısına yetmediğinde derleyicinin bazı değişkenleri geçici olarak RAM üzerindeki çağrı yığınına yazıp geri okumasına ne ad verilir?', 'Yazmaç taşması / dökülmesi (register spilling)', ['Yığın taşması (stack overflow)', 'Bellek sızıntısı (memory leak)', 'Sayfa hatası (page fault)'], 'Yazmaçlara sığmayan değişkenlerin yığın belleğe (stack frame) aktarılmasına register spilling denir.'),
  ('Bir JIT derleyicinin, çalışma öncesinde derleme yapan geleneksel bir AOT (Ahead-Of-Time) derleyiciye göre sahip olduğu en önemli bilgi avantajı nedir?', 'Gerçek çalışma zamanı veri dağılımlarını, dal olasılıklarını ve dinamik tip profillerini gözlemleyerek spekülatif eniyileştirme yapabilmesi', ['Kaynak koddaki sözdizimi hatalarını program hiç çalıştırılmadan önce %100 oranında saptayabilmesi', 'Çalışma zamanında hiçbir ek bellek veya işlemci süresi harcamadan sıfır maliyetle kod üretebilmesi', 'Hedef makinede işletim sistemi ve işlemci olmadan doğrudan kaynak metin üzerinden çalışabilmesi'], 'JIT derleyici o çalışmada gerçekten hangi alt sınıfların ve dalların kullanıldığını görerek spekülatif satır içi açma gibi agresif eniyileştirmeler yapabilir.'),
  ('JIT derleyicinin çalışma zamanı profiline güvenerek yaptığı spekülatif bir varsayım (örneğin bir değişkenin hep tam sayı gelmesi) ilerleyen adımlarda bozulduğunda doğruluğu korumak için uyguladığı geri dönüş mekanizmasına ne ad verilir?', 'Eniyileştirmeyi geri alma / deoptimizasyon (deoptimization / bailout)', ['Sözcüksel geri izleme (lexical backtracking)', 'Derleme zamanı sabit katlama (constant folding)', 'Statik tekil atama birleştirme (SSA phi-merging)'], 'Varsayım muhafızı (guard) başarısız olduğunda JIT kodu yürütme durumunu güvenli biçimde yorumlayıcıya veya temel koda devreder; buna deoptimization denir.'),
  ('JIT veya gelişmiş derleyicilerde bir nesnenin oluşturulduğu fonksiyon dışına hiç çıkmadığını (başka iş parçacıklarına veya genel alanlara sızmadığını) kanıtlayarak küme (heap) yerine yığında (stack) veya yazmaçlarda tutulmasını sağlayan analiz hangisidir?', 'Kaçış analizi (escape analysis)', ['Sol özyineleme analizi (left-recursion analysis)', 'Sözdizimi kurtarma analizi (panic-mode recovery)', 'Belirteç sınır analizi (boundary tokenization)'], 'Escape analysis nesnenin kapsam dışına kaçmadığını kanıtlarsa çöp toplayıcı (GC) yükünü azaltacak şekilde yığın tahsisi veya skaler ikame uygular.'),
  ('S -> ( S ) S | ε grameriyle ()() dizgisi türetilirken en soldan türetme (leftmost derivation) adımları doğru sırayla nasıl gerçekleşir?', 'S => (S)S => ()S => ()(S)S => ()()S => ()()', ['S => (S)S => (S)(S)S => ()(S)S => ()()S => ()()', 'S => ()() => (ε)(ε) => S', 'S => ((S)) => ()()'], 'En soldan türetmede her adımda en soldaki S açılır: S => (S)S => ()S [ilk S->ε] => ()(S)S [kalan S açılır] => ()()S => ()().'),
  ('Kapsam (scope) kurallarında bir fonksiyonun içinde geçen serbest bir değişkenin çağrı yığınındaki en son çağıran fonksiyona göre değil, kaynak kodda metinsel olarak tanımlandığı çevreleyen bloğa göre çözümlenmesine ne ad verilir?', 'Sözcüksel (statik) kapsam (lexical / static scoping)', ['Dinamik çağrı kapsamı (dynamic scoping)', 'Küresel ad alanı çakışması (global aliasing)', 'Geçici yazmaç ömrü (register liveness)'], 'Modern dillerin neredeyse tamamında kullanılan ve değişken bağlamasını kaynak kodun metinsel blok yapısına göre belirleyen kural sözcüksel (statik) kapsamdır.'),
  ('Bir fonksiyonun kendi sözcüksel kapsamı dışındaki çevreleyen fonksiyona ait yerel değişkenleri, çevreleyen fonksiyon sonlandıktan sonra bile yakalayıp yaşatabilmesini sağlayan çalışma zamanı yapısına ne ad verilir?', 'Kapanış (closure)', ['Sözdizimi belirteci (lexeme)', 'Ayrıştırma tablosu (parse table)', 'Temel blok (basic block)'], 'Fonksiyon kodu işaretçisi ile yakalanan serbest değişken ortamını birlikte paketleyen yapıya kapanış (closure) denir.'),
  ('Üç adresli ara kodda t1 = a * b, t2 = t1 + c, d = t2 - t1 komut dizisi özyinelemesiz bir ifade çizgesine dönüştürüldüğünde t1 düğümünün iki farklı yerden ortak kullanılması hangi yapıyı oluşturur?', 'Yönlü Çevrimsiz Çizge (DAG - Directed Acyclic Graph)', ['Doğrusal Bağlı Liste (Singly Linked List)', 'Döngüsel Durum Otomatı (Cyclic DFA)', 'Kısıtsız İkili Yığın (Binary Heap)'], 'Ortak alt ifadelerin paylaşıldığı ifade temsilleri ağaç yerine Yönlü Çevrimsiz Çizge (DAG) oluşturur.'),
  ('Yığın tabanlı sanal makine (stack VM) ile yazmaç tabanlı sanal makine (register VM, örneğin Lua VM veya Dalvik) karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Yığın VM bayt kodu daha kısa komutlardan oluşurken daha fazla komut dağıtımı (dispatch) yapar; yazmaç VM ise daha az komutla ancak daha uzun komut kodlamasıyla çalışır', ['Yığın VM hiçbir zaman aritmetik işlem yapamazken yazmaç VM yalnızca metin dizgilerini işleyebilir', 'Yazmaç VM çalışmak için fiziksel donanım yazmaç sayısının sonsuz olmasını zorunlu kılar', 'Yığın VM derleme zamanında tip denetimine izin vermezken yazmaç VM yalnızca derlenemeyen dillerde kullanılır'], 'Yığın VM\'de operand adresleri örtük olduğundan komutlar küçüktür ama PUSH/POP sayısı fazladır; yazmaç VM operand indislerini komutta taşır ve toplam komut sayısını azaltır.'),
  ('Bir özyinelemeli iniş ayrıştırıcısında ifade() fonksiyonu terim() fonksiyonunu, terim() fonksiyonu carpan() fonksiyonunu, carpan() ise parantez gördüğünde yeniden ifade() fonksiyonunu çağırmaktadır. (((5))) girdisi ayrıştırılırken bu üç fonksiyon arasındaki ilişki hangi kavramı örneklendirir?', 'Dolaylı (karşılıklı) özyineleme ve iç içe parantez derinliğiyle orantılı çağrı yığını büyümesi', ['Kuyruk özyinelemesi sayesinde sabit O(1) yığın çerçevesinde çalışma', 'Bağlama duyarlı tip çıkarımı ile çalışma zamanı bellek sızıntısı', 'Alttan yukarı kaydır-indirge tablosunda durum sıkıştırması'], 'ifade -> terim -> carpan -> ifade döngüsü karşılıklı özyinelemedir ve her açılan parantez çağrı yığını derinliğini bir kademe artırır.'),
  ('Üç adresli ara kod üreticisi a = b + c * d ifadesini derlerken öncelik kurallarına uygun olarak aşağıdaki ara kod dizilerinden hangisini üretmelidir?', 't1 = c * d ardından t2 = b + t1 ardından a = t2', ['t1 = b + c ardından t2 = t1 * d ardından a = t2', 't1 = a + b ardından c = t1 * d ardından b = c', 'a = b ardından t1 = a * c ardından d = t1'], 'Çarpma işlemi toplamadan yüksek öncelikli olduğundan AST\'de alt düğümdeki c * d önce t1 geçici değişkenine hesaplanır, sonra b ile toplanıp a\'ya atanır.'),
];
